import {compositions,teamAnalysis,rankAugments,recommendItems} from './engine.js';
import {scanScreenshot} from './scan.js';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,state,tab='team',pickerTarget=null,sort='winrate',role='All',search='',scanning=false,scanPreview=null;
const initial=()=>({team:[null,null,null,null,null],bench:[],locked:[],player:null,enemies:[null,null,null,null,null],offered:[null,null,null],owned:[],mode:'synergy'});
const champ=id=>data.champions.find(c=>c.slug===id);const aug=id=>data.augments.find(a=>a.augment_id===id);const team=()=>state.team.map(champ).filter(Boolean);const enemies=()=>state.enemies.map(champ).filter(Boolean);
const fmt=n=>Number(n).toFixed(2);const icon=src=>src?.startsWith('/icons/')?'https://mayhemmeta.com'+src:'';
const portrait=(c,cls='')=>`<img class="portrait ${cls}" src="${icon(c.icon_url)}" alt="" loading="lazy">`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function save(){try{localStorage.setItem('mayhemnator-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable; this session will not persist.');}}
function load(){const s=initial();try{const v=JSON.parse(localStorage.getItem('mayhemnator-v1'));if(v){const valid=id=>typeof id==='string'&&champ(id)?id:null;s.team=Array.from({length:5},(_,i)=>valid(v.team?.[i]));s.team=s.team.map((id,i,a)=>id&&a.indexOf(id)!==i?null:id);s.bench=[...new Set((v.bench||[]).map(valid).filter(id=>id&&!s.team.includes(id)))].slice(0,10);s.locked=(v.locked||[]).filter(id=>s.team.includes(id));s.enemies=Array.from({length:5},(_,i)=>valid(v.enemies?.[i]));s.enemies=s.enemies.map((id,i,a)=>id&&(a.indexOf(id)!==i||s.team.includes(id))?null:id);s.player=valid(v.player);s.owned=[...new Set((v.owned||[]).filter(id=>aug(id)))].slice(0,8);s.offered=Array.from({length:3},(_,i)=>aug(v.offered?.[i])&&!s.owned.includes(v.offered[i])?v.offered[i]:null);s.mode=v.mode==='winrate'?'winrate':'synergy';}}catch{}return s;}
const sectionHead=(n,title,extra='')=>`<div class="section-head"><h2><span class="step">${n}</span>${title}</h2>${extra}</div>`;
const hero=(label,title,description)=>`<section class="hero"><div><div class="eyebrow"><i></i> YOUR ARAM: MAYHEM COMPANION <span>/ ${label}</span></div><h1>${title}</h1><p>${description}</p></div><div class="snapshot"><span class="status-dot"></span> SNAPSHOT <b>${new Date(data.fetchedAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</b><small>Patch ${esc(data.champions.find(c=>c.patch)?.patch||'unknown')} · ${data.champions.length} champions</small></div></section>`;
function slot(id,i,type){const c=champ(id);return c?`<div class="champ-slot filled ${state.locked.includes(id)&&type==='team'?'locked':''}"><button class="remove" data-remove="${type}:${i}" aria-label="Remove ${esc(c.name)}">×</button><button class="slot-select" data-picker="${type}:${i}">${portrait(c)}<span class="slot-number">${type==='team'?`ALLY 0${i+1}`:`ENEMY 0${i+1}`}</span><strong>${esc(c.name)}</strong><span class="slot-role">${esc(c.roles.join(' / '))}</span><span class="rate">${fmt(c.wr)}% <small>WR</small></span></button>${type==='team'?`<button class="lock-button ${state.locked.includes(id)?'selected':''}" data-lock="${id}">${state.locked.includes(id)?'▣ Locked':'◇ Lock pick'}</button>`:''}</div>`:`<button class="champ-slot empty" data-picker="${type}:${i}"><span class="slot-number">${type==='team'?`ALLY 0${i+1}`:`ENEMY 0${i+1}`}</span><span class="plus">+</span><strong>Add champion</strong><small>${type==='team'?'Your current pick':'Optional'}</small></button>`;}
const scanZone=()=>`<div class="scan-zone ${scanning?'busy':''}" data-dropzone><span class="scan-icon">${scanning?'◌':'⇪'}</span><div><strong>${scanning?'Reading your champ select…':'Scan a champ select screenshot'}</strong><small>${scanning?'Matching champion icons. The first scan downloads Riot’s icons and takes a few seconds.':'Drop an image here, press Ctrl+V anywhere on the site, or upload. Free and runs in your browser. Fills your team and bench.'}</small></div><div class="scan-actions"><button class="secondary" data-scan ${scanning?'disabled':''}>Upload screenshot</button>${scanPreview?'<button class="text-button" data-hide-preview>Hide preview</button>':''}</div><input type="file" id="scan-file" accept="image/*" hidden></div>${scanPreview?`<div class="scan-preview"><img src="${scanPreview.url}" alt="Scanned screenshot">${scanPreview.boxes.map(b=>`<span class="scan-box ${b.kind}" title="${esc(champ(b.slug)?.name)} · ${Math.round(b.score*100)}% match" style="left:${b.x*100}%;top:${b.y*100}%;width:${b.s*b.h/b.w*100}%;height:${b.s*100}%"><i>${esc(champ(b.slug)?.name)}</i></span>`).join('')}</div><p class="helper">Green = ally, violet = bench. Wrong or missing? Click a slot below to fix it.</p>`:''}`;
async function runScan(file){if(!file?.type?.startsWith('image/')){toast('That file is not an image.');return;}if(scanning)return;scanning=true;if(tab!=='team'){tab='team';history.replaceState(null,'','#team');}render();window.scrollTo({top:0,behavior:'smooth'});
 try{const r=await scanScreenshot(file,data);if(scanPreview)URL.revokeObjectURL(scanPreview.url);scanPreview={url:URL.createObjectURL(file),boxes:r.boxes};if(!r.allies.length&&!r.bench.length){toast('No champions recognized. Try a full-screen champ select screenshot.');return;}
  state.team=Array.from({length:5},(_,i)=>r.allies[i]||null);state.bench=r.bench;state.locked=[];state.enemies=state.enemies.map(id=>id&&![...r.allies,...r.bench].includes(id)?id:null);
  if(r.player&&state.player!==r.player){state.player=r.player;state.owned=[];state.offered=[null,null,null];}tab='team';
  toast(`Found ${r.allies.length} allies and ${r.bench.length} bench champions. Check them, then use the recommended lineup.`);
   scanning=false;render();document.querySelector('.recommendations')?.scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){toast(e.message);console.error(e);}finally{if(scanning){scanning=false;render();}}}
function renderTeam(){const current=team();const analysis=teamAnalysis(current);const pool=[...current,...state.bench.map(champ).filter(Boolean)];const results=compositions(pool,state.locked,state.mode);
 return hero('DRAFT','A little less random.<br><span>A lot more Mayhem.</span>','Find the strongest five from your team and bench. Make every roll count.')+`<div class="workspace"><div class="main-column"><section class="panel">${sectionHead('01','Your team',`<div class="inline"><span class="muted">${current.length}/5 selected</span><button class="text-button" data-example>Load example</button></div>`)}<p class="helper">Add your current champions. Lock any picks you want to keep.</p>${scanZone()}<div class="team-slots">${state.team.map((id,i)=>slot(id,i,'team')).join('')}</div><div class="bench-head"><h3>On the bench <span>${state.bench.length}/10</span></h3><span class="muted">Rerolls & available swaps</span></div><div class="bench">${state.bench.map((id,i)=>{const c=champ(id);return `<div class="bench-chip">${portrait(c)}<span>${esc(c.name)}<small>${fmt(c.wr)}% WR</small></span><button data-remove="bench:${i}" aria-label="Remove ${esc(c.name)} from bench">×</button></div>`;}).join('')}<button class="add-bench" data-picker="bench:0" ${pool.length>=15?'disabled':''}>+ Add champion</button></div></section>
 <section class="panel recommendations">${sectionHead('02','Find your best five',`<div class="segmented" aria-label="Composition ranking"><button data-mode="synergy" class="${state.mode==='synergy'?'selected':''}">✧ Synergy</button><button data-mode="winrate" class="${state.mode==='winrate'?'selected':''}">Win rate</button></div>`)}<p class="helper">${state.mode==='synergy'?'Champion performance + class coverage + published teammate results.':'Ranked by average individual champion win rate. No synergy adjustment.'}</p>${results.length?results.map((r,i)=>`<article class="comp-row ${i===0?'best':''}"><span class="comp-rank">${String(i+1).padStart(2,'0')}</span><div class="comp-main"><div class="inline"><strong>${i===0?'Recommended lineup':`Alternative ${i}`}</strong>${i===0?'<span class="badge">BEST IN YOUR POOL</span>':''}</div><div class="mini-team">${r.team.map(c=>`<span>${portrait(c)}${esc(c.name)}</span>`).join('')}</div><div class="coverage">${r.coverage.map(([label,yes])=>`<span class="${yes?'good':'missing'}">${yes?'✓':'−'} ${label}</span>`).join('')}</div></div><div class="comp-score"><strong>${fmt(state.mode==='synergy'?r.score:r.average)}${state.mode==='winrate'?'%':''}</strong><small>${state.mode==='synergy'?'ranking score':'mean champion WR'}</small><button class="text-button" data-use="${r.team.map(c=>c.slug).join(',')}">Use team →</button></div></article>`).join(''):`<div class="empty-state"><span>✧</span><h3>Your best lineup starts here</h3><p>Add at least five champions across your team and bench.<br>We’ll compare every available combination.</p></div>`}<div class="footnote">ⓘ Scores and mean champion win rates are not predicted team win probabilities.</div></section></div>
 <aside><section class="panel insight"><span class="eyebrow">THE BIG PICTURE</span><h2>Team identity</h2>${current.length?`<div class="big-number">${fmt(analysis.average)}<span>%</span></div><p class="muted">Mean champion win rate · ${current.length}/5 picks</p><div class="identity-list">${analysis.coverage.map(([label,yes])=>`<div><span>${label}</span><b class="${yes?'good':'missing'}">${yes?'Covered':'Missing'}</b></div>`).join('')}</div><p class="helper">Class-based estimates; augments can change a champion’s role.</p>${analysis.pairs.length?`<h3>Published pair signals</h3>${analysis.pairs.slice(0,3).map(p=>`<div class="pair"><b>${esc(p.names.join(' + '))}</b><span>${fmt(p.wr)}% duo WR · ~${p.n} games</span></div>`).join('')}`:'<p class="helper">No published pair samples for these picks.</p>'}`:`<div class="identity-empty">◎</div><p class="helper">Your damage, frontline, and utility coverage will appear as you add champions.</p>`}<button class="primary wide" data-tab="advisor">Go to live advisor <span>→</span></button></section><div class="tip"><span>✦</span><div><h3>More than a tier list.</h3><p>The highest-win-rate picks don’t always make the most balanced team. Add bench options to explore the tradeoff.</p></div></div><button class="quiet reset" data-reset>↺ Reset session</button></aside></div>`;
}
function augmentInput(id,label,value){return `<label class="field">${label}<input list="augment-list" data-augment="${id}" value="${esc(aug(value)?.name||'')}" placeholder="Type an augment name…" autocomplete="off"></label>`;}
function renderAdvisor(){const c=champ(state.player);const ranked=c?rankAugments(c,state.offered.filter(Boolean),state.owned,enemies(),team().filter(t=>t.slug!==c.slug)):[];const build=c?recommendItems(c,state.owned,enemies(),data.augments):null;
return hero('IN GAME','Your next pick.<br><span>Your next power spike.</span>','Compare the augments on your screen and adapt your build as the game changes.')+`<datalist id="augment-list">${data.augments.map(a=>`<option value="${esc(a.name)}">${a.rarity}</option>`).join('')}</datalist><div class="workspace"><div class="main-column"><section class="panel">${sectionHead('01','Your champion')}<div class="player-picker">${c?portrait(c):'<span class="player-empty">?</span>'}<div><h2>${c?esc(c.name):'Who are you playing?'}</h2><p class="helper">${c?`${esc(c.roles.join(' / '))} · ${fmt(c.wr)}% champion WR`:'Choose your champion to load their augment and item data.'}</p></div><button class="secondary" data-picker="player:0">${c?'Change champion':'Select champion'}</button></div>${team().length?`<div class="quick-picks">${team().map(t=>`<button data-player="${t.slug}" class="${state.player===t.slug?'selected':''}">${portrait(t)}${esc(t.name)}</button>`).join('')}</div>`:''}</section>
<section class="panel">${sectionHead('02','What’s on your screen?',`<button class="text-button" data-clear-offers>Clear offers</button>`)}<p class="helper">Enter up to three offered augments. Owned augments are included in combo scoring.</p><div class="offer-inputs">${state.offered.map((id,i)=>augmentInput(i,`OPTION 0${i+1}`,id)).join('')}</div>${ranked.length?`<div class="augment-results">${ranked.map((r,i)=>{const a=aug(r.id);return `<article class="augment-card ${i===0&&r.available?'recommended':''}"><div class="augment-top"><img src="${icon(a.icon_url)}" alt=""><div><span class="rarity ${a.rarity.toLowerCase()}">${esc(a.rarity)}</span><h3>${esc(a.name)}</h3></div>${i===0&&r.available?'<span class="badge">TOP PICK</span>':''}</div>${r.available?`<div class="augment-numbers"><div><strong>${fmt(r.wr)}%</strong><small>observed champion WR</small></div><div><strong>${fmt(r.score)}</strong><small>adjusted ranking score</small></div></div>`:'<p class="missing">Not ranked · insufficient data</p>'}<ul class="reasons">${r.reasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="${i===0&&r.available?'primary':'secondary'} wide" data-pick="${r.id}">I picked this <span>+</span></button></article>`;}).join('')}</div>`:`<div class="small-empty">${c?'Enter your offers above to compare them.':'Select your champion, then enter the augments you see.'}</div>`}<div class="owned"><h3>Already picked <span>${state.owned.length}/8</span></h3><div class="owned-list">${state.owned.map(id=>`<button class="owned-chip" data-unpick="${id}" aria-label="Remove owned augment ${esc(aug(id)?.name)}">${esc(aug(id)?.name)} <span>×</span></button>`).join('')||'<span class="muted">No augments selected yet</span>'}</div>${augmentInput('owned','ADD AN EARLIER PICK',null)}</div></section>
<section class="panel">${sectionHead('03','Enemy team',`<span class="muted">Optional context</span>`)}<p class="helper">Enemy classes inform a few item and augment adjustments. Your ally context comes from the team builder.</p><div class="team-slots enemies">${state.enemies.map((id,i)=>slot(id,i,'enemies')).join('')}</div></section></div>
<aside><section class="panel build"><span class="eyebrow">SPEND GOLD WITH PURPOSE</span><h2>Build priorities</h2><p class="helper">Situational item shortlist. Priority order is estimated, not a measured purchase sequence.</p>${build?.items.length?`<div class="build-list">${build.items.map((item,i)=>`<details class="build-item"><summary><span class="item-number">${i+1}</span><img src="${icon(item.icon)}" alt=""><span><strong>${esc(item.name)}</strong><small>${fmt(item.wr)}% WR · ${fmt(item.pick)}% pick</small></span><span class="chevron">⌄</span></summary><p>${item.reasons.map(esc).join(' ')} Approximately ${item.n.toLocaleString()} games.</p></details>`).join('')}</div>${build.boots?`<div class="boots"><img src="${icon(build.boots.icon)}" alt=""><div><small>BOOT OPTION</small><strong>${esc(build.boots.name)}</strong><span>${fmt(build.boots.wr)}% observed WR</span></div></div>`:''}<a class="source-link" href="https://mayhemmeta.com/champions/${c.slug}" target="_blank" rel="noreferrer">Explore ${esc(c.name)}’s source data ↗</a>`:`<div class="identity-empty">◇</div><p class="helper">${c?'No item data is available for this champion.':'Select a champion to see build priorities.'}</p>`}</section><div class="tip"><span>✦</span><div><h3>The reason matters.</h3><p>Expand an item to see why it’s suggested. Context adjustments are estimates; observed win rates stay unchanged.</p></div></div></aside></div>`;
}
function statRows(){const list=data.champions.filter(c=>(role==='All'||c.roles.includes(role))&&c.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='pick'?b.pick-a.pick:b.wr-a.wr);return list.length?list.map((c,i)=>`<tr><td class="muted">${String(i+1).padStart(2,'0')}</td><td><button class="table-champ" data-player="${c.slug}">${portrait(c)}<span>${esc(c.name)}<small>${esc(c.roles.join(' / '))}</small></span></button></td><td><span class="tier tier-${c.tier}">${c.tier}</span></td><td><b class="${c.wr>=50?'good':''}">${fmt(c.wr)}%</b><div class="rate-bar"><i style="width:${Math.min(100,Math.max(0,(c.wr-35)*4))}%"></i></div></td><td>${fmt(c.pick)}%</td><td>${c.games?.toLocaleString()||'—'}</td><td><button class="text-button" data-add="${c.slug}" ${[...state.team,...state.bench].includes(c.slug)?'disabled':''}>${[...state.team,...state.bench].includes(c.slug)?'Added':'Add to pool +'}</button></td></tr>`).join(''):'<tr><td colspan="7" class="small-empty">No champions match your filters.</td></tr>';}
function renderStats(){return hero('THE META','Know the field.<br><span>Find your advantage.</span>','Every champion, ranked by observed ARAM: Mayhem performance.')+`<section class="panel stats-panel"><div class="section-head"><h2>Champion leaderboard</h2><input type="search" id="stats-search" placeholder="Search champions…" aria-label="Search champion leaderboard" value="${esc(search)}"></div><div class="filters">${['All','Tank','Fighter','Mage','Marksman','Support','Assassin'].map(r=>`<button class="${role===r?'selected':''}" data-role="${r}">${r}</button>`).join('')}<label class="sort">Sort by <select id="stats-sort"><option value="winrate" ${sort==='winrate'?'selected':''}>Win rate</option><option value="pick" ${sort==='pick'?'selected':''}>Pick rate</option><option value="name" ${sort==='name'?'selected':''}>Name</option></select></label></div><div class="table-scroll"><table><thead><tr><th>#</th><th>Champion</th><th>Tier</th><th>Win rate</th><th>Pick rate</th><th>Games</th><th>Plan your team</th></tr></thead><tbody id="stats-body">${statRows()}</tbody></table></div><div class="footnote">Source tiers and win rates are from the snapshot date. Click a champion to open their advisor.</div></section>`;}
function render(){document.querySelectorAll('nav [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');});$('#app').innerHTML=tab==='team'?renderTeam():tab==='advisor'?renderAdvisor():renderStats();save();}
function setPlayer(id){if(state.player!==id){state.player=id;state.owned=[];state.offered=[null,null,null];}tab='advisor';render();}
function openPicker(target){pickerTarget=target;$('#picker-title').textContent=target.startsWith('bench')?'Add a bench option':target.startsWith('player')?'Your champion':target.startsWith('enemies')?'Choose an enemy':'Choose an ally';$('#picker-search').value='';pickerRows();$('#picker').showModal();$('#picker-search').focus();}
function pickerRows(){const q=$('#picker-search').value.toLowerCase();const type=pickerTarget.split(':')[0];const blocked=type==='enemies'?[...state.enemies,...state.team,state.player]:type==='player'?state.enemies:[...state.team,...state.bench,...state.enemies];$('#picker-results').innerHTML=data.champions.filter(c=>c.name.toLowerCase().includes(q)).map(c=>`<button data-choose="${c.slug}" ${blocked.includes(c.slug)?'disabled':''}>${portrait(c)}<strong>${esc(c.name)}</strong><small>${fmt(c.wr)}% WR</small></button>`).join('')||'<p>No matching champions.</p>';}
function addPool(id){if([...state.team,...state.bench,...state.enemies].includes(id)){toast('That champion is already selected.');return;}const empty=state.team.indexOf(null);if(empty>=0)state.team[empty]=id;else if(state.bench.length<10)state.bench.push(id);else{toast('Your pool is full (15 champions).');return;}render();toast(`${champ(id).name} added to your pool.`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled||!data)return;
 if(b.dataset.tab){tab=b.dataset.tab;location.hash=tab;render();}
 if(b.dataset.picker)openPicker(b.dataset.picker);
 if(b.hasAttribute('data-scan'))$('#scan-file').click();
 if(b.hasAttribute('data-hide-preview')){URL.revokeObjectURL(scanPreview.url);scanPreview=null;render();}
 if(b.dataset.choose){const id=b.dataset.choose;const [type,index]=pickerTarget.split(':');if(type==='player')setPlayer(id);else if(type==='bench')state.bench.push(id);else {const old=state[type][+index];state.locked=state.locked.filter(x=>x!==old);state[type][+index]=id;}$('#picker').close();render();}
 if(b.dataset.remove){const [type,index]=b.dataset.remove.split(':');const old=state[type][+index];state.locked=state.locked.filter(x=>x!==old);if(type==='bench')state.bench.splice(+index,1);else state[type][+index]=null;render();}
 if(b.dataset.lock){const id=b.dataset.lock;state.locked=state.locked.includes(id)?state.locked.filter(x=>x!==id):[...state.locked,id];render();}
 if(b.hasAttribute('data-example')){state=initial();state.team=['jinx','ahri','leona','sona','sett'];state.bench=['gwen','lillia','alistar'];state.player='jinx';render();toast('Example loaded. Replace picks with your own lobby.');}
 if(b.dataset.mode){state.mode=b.dataset.mode;render();}
 if(b.dataset.use){const next=b.dataset.use.split(',');state.bench=[...state.team,...state.bench].filter(id=>id&&!next.includes(id));state.team=next;render();toast('Recommended lineup applied. Other picks moved to the bench.');}
 if(b.dataset.player)setPlayer(b.dataset.player);
 if(b.dataset.add)addPool(b.dataset.add);
 if(b.hasAttribute('data-clear-offers')){state.offered=[null,null,null];render();}
 if(b.dataset.pick){if(state.owned.length>=8){toast('Remove an owned augment before adding another.');return;}state.owned.push(+b.dataset.pick);state.offered=[null,null,null];render();toast('Pick recorded. Build priorities updated.');}
 if(b.dataset.unpick){state.owned=state.owned.filter(id=>id!==+b.dataset.unpick);render();}
 if(b.dataset.role){role=b.dataset.role;render();}
 if(b.hasAttribute('data-reset')){state=initial();render();toast('Session cleared.');}
});
document.addEventListener('change',e=>{if(e.target.id==='scan-file'){runScan(e.target.files[0]);e.target.value='';return;}if(e.target.id==='stats-sort'){sort=e.target.value;$('#stats-body').innerHTML=statRows();}if(e.target.dataset.augment!==undefined){const input=e.target;const target=input.dataset.augment;const value=input.value.trim();if(!value){if(target!=='owned')state.offered[+target]=null;render();return;}const a=data.augments.find(a=>a.name.toLowerCase()===value.toLowerCase());if(!a){input.setCustomValidity('Choose an augment from the list.');input.reportValidity();return;}if(state.owned.includes(a.augment_id)||state.offered.some((id,i)=>id===a.augment_id&&String(i)!==target)){input.setCustomValidity('This augment is already selected.');input.reportValidity();return;}if(target==='owned'){if(state.owned.length>=8){toast('Maximum eight owned augments.');return;}state.owned.push(a.augment_id);}else state.offered[+target]=a.augment_id;render();}});
document.addEventListener('input',e=>{e.target.setCustomValidity?.('');if(e.target.id==='picker-search')pickerRows();if(e.target.id==='stats-search'){search=e.target.value;$('#stats-body').innerHTML=statRows();}});
// Ctrl+V an image anywhere to scan it; text fields still get pasted text as usual.
document.addEventListener('paste',e=>{if(!data)return;const file=[...(e.clipboardData?.files||[])].find(f=>f.type.startsWith('image/'));if(!file||(e.target.closest?.('input,textarea')&&e.clipboardData.getData('text')))return;e.preventDefault();document.querySelectorAll('dialog[open]').forEach(d=>d.close());runScan(file);});
document.addEventListener('dragover',e=>{const z=e.target.closest?.('[data-dropzone]');if(z){e.preventDefault();z.classList.add('over');}});
document.addEventListener('dragleave',e=>e.target.closest?.('[data-dropzone]')?.classList.remove('over'));
document.addEventListener('drop',e=>{const z=e.target.closest?.('[data-dropzone]');if(z){e.preventDefault();z.classList.remove('over');runScan(e.dataTransfer.files[0]);}});
$('#close-picker').onclick=()=>$('#picker').close();$('#method-button').onclick=()=>$('#method').showModal();$('#close-method').onclick=()=>$('#method').close();
window.addEventListener('hashchange',()=>{if(['team','advisor','stats'].includes(location.hash.slice(1))){tab=location.hash.slice(1);if(data)render();}});
try{const r=await fetch('data.json');if(!r.ok)throw Error('Snapshot request failed');data=await r.json();state=load();tab=['team','advisor','stats'].includes(location.hash.slice(1))?location.hash.slice(1):'team';$('#method-data').textContent=`Snapshot: ${data.fetchedAt}. ${data.champions.length} champions, ${data.augments.length} augments. ${data.errors.length} champion detail failures. Refresh the snapshot using the included Python script.`;render();}catch(e){$('#app').innerHTML='<div class="panel error"><h1>Could not load the snapshot</h1><p>Check that data.json is available and serve the app with npm start.</p><button class="primary" onclick="location.reload()">Try again</button></div>';console.error(e);}
